/**
 * 取某个分组的图标
 *
 * @param string $key 分组 id。
 * @return string
 */
function echo_settings_icon( $key ) {
	$icons = echo_settings_icons();
	return isset( $icons[ $key ] ) ? $icons[ $key ] : '';
}
